import math
def interp(points,u):
    points=sorted(points)
    for a,b in zip(points,points[1:]):
        if a[0]<=u<=b[0]:
            return a[1]+(b[1]-a[1])*(u-a[0])/max(0.001,b[0]-a[0])
    return min(points,key=lambda p:abs(p[0]-u))[1]
def control(obs):
    h=obs['hitch_deg']
    cam=obs.get('views',{}).get('camera')
    desired=0
    if cam:
        sides=[[],[]]
        for b,d in cam.get('walls',[]):
            a=math.radians(b+h)
            u=-d*math.cos(a); v=d*math.sin(a)
            if u>0.5:
                sides[0 if v<0 else 1].append((u,v))
        if all(sides):
            u=3.8
            v=(interp(sides[0],u)+interp(sides[1],u))/2
            desired=math.degrees(math.atan2(5.2*v,u*u+v*v))
            desired=max(-28,min(28,desired))
    steer=max(-34,min(34,0.75*h+1.8*(h-desired)))
    return steer,-0.7,-23

